files.concepts.memql:
/// A loop scenario row.
@namespace("loopself")
concept ticket {
  key string
  status string
  n int
}

files.mutations.memql:
/// Write a scenario row.
mutation ticket loopSelfCreate {
  args {
    id string!
    status string
    n int
  }
  insert {
    id: args.id
    key: args.id
    status: args.status
    n: args.n
  }
}
/// Write a scenario row.
mutation ticket loopSelfUpdate {
  args {
    id string!
    status string
    n int
  }
  update {
    id: args.id
    key: args.id
    status: args.status
    n: args.n
  }
}

scenarios.automations:
/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:loopself:ticket")
automation loopSelfAdvance {
  args {
    id any
    key any
    status any
    n any
  }
  mutation loopSelfUpdate(id: args.key, n: args.n + 1, status: args.n >= 1 ? "done" : "open")
}

/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:loopself:ticket")
@filter(row => row.status != "done")
@loop(maxDepth=4, until=row => row.status == "done")
automation loopSelfAdvance {
  args {
    id any
    key any
    status any
    n any
  }
  mutation loopSelfUpdate(id: args.key, n: args.n + 1, status: args.n >= 1 ? "done" : "open")
}

/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:loopself:ticket")
@filter(row => row.status != "done")
@loop(maxDepth=4, until=row => row.status == "done")
automation loopSelfAdvance {
  args {
    id any
    key any
    status any
    n any
  }
  mutation loopSelfUpdate(id: args.key, n: args.n + 1, status: "open")
}

/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:loopself:ticket")
automation loopSelfAdvance {
  args {
    id any
    key any
    status any
    n any
  }
  builtin loopScenarioOpaqueWrite(id: args.key, n: args.n + 1, status: "open")
}
